BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_vid'
def S(w):return 'https://www.etymonline.com/word/'+w
def O(w):return 'https://www.oxfordlearnersdictionaries.com/definition/english/'+w
def K(w):return 'https://en.wiktionary.org/wiki/'+w
def M(w):return 'https://www.merriam-webster.com/dictionary/'+w
RHE='https://www.rheumatology.org.uk/what-is-rheumatology'
W=[
E('rhythm','英、美 /ˈrɪðəm/','节奏；韵律；有规律反复出现的模式','声音、动作或生活进程不是乱成一团，而是在时间里呈现出能感到的长短、强弱和重复。','接拉丁 rhythmus、希腊 rhythmos“有秩序的运动、节律”，与 rhein“流动”相连。英语现代拼写还受重新靠近古典词形的影响，与经法语 rime 进入英语的旧形式有交织；不要把今天的 rhythm 当作 rhyme 的直接母词。',[['希腊 rhein／rhythmos','流动；有安排的运动、节律'],['拉丁 rhythmus 与法语、中古英语 rime 词族','韵律、诗的节拍等'],['英语恢复古典式拼写 rhythm','节奏；音乐、语言、身体与生活的规律']],'音乐里 rhythm 是声音长短、重音和停顿的安排，不只是均匀的“咚咚”拍子。settle into a rhythm 也能说逐渐找到做事的节奏；heart rhythm 指心脏跳动的节律。','a steady rhythm；the rhythm of speech；get into a rhythm；heart rhythm；rhythm and blues。','beat 常是可数出的基本拍；rhythm 是声音在拍点之间如何安排。rhyme 是押韵，关心尾音相似，而不是时间上的节奏。',('The drummer changed the rhythm without changing the tempo.','鼓手改变了节奏型，但没有改变速度。'),('After a few days, we found a comfortable rhythm for working together.','几天之后，我们找到了舒服的合作节奏。'),sources=[S('rhythm'),O('rhythm'),K('rhythm')]),
E('rhythmic','英、美 /ˈrɪðmɪk/','有节奏的；与节奏有关的','能听见或感觉到反复的强弱、长短与起伏，让动作或声音有一个可跟随的模式。','经法语 rhythmique 或拉丁 rhythmicus，接希腊 rhythmikos“有节律的”。现代可以按 rhythm + -ic 理解，但形容词有自己的古典借入路线。',[['希腊 rhythmos → rhythmikos','节律 → 有节律的'],['拉丁 rhythmicus／法语 rhythmique → 英语 rhythmic','与节奏有关的'],['音乐、运动和日常声音','有反复的拍点、强弱或动作模式']],'rhythmic breathing 是有规律的呼吸；rhythmic gymnastics 是艺术体操，动作与节奏紧密配合。rhythmic 也能只表示“节奏方面的”，例如 rhythmic complexity 是节奏结构复杂，不是在评价是否好听。','rhythmic movement；rhythmic breathing；rhythmic patterns；rhythmic gymnastics。','regular 只是规律的；rhythmic 更突出时间里的起伏与重复。rhythmical 是意思接近的另一形容词形式。',('We heard the rhythmic sound of wheels passing over the rails.','我们听见车轮驶过铁轨时有节奏的声音。'),('The piece is known for its rhythmic complexity.','这首作品以复杂的节奏著称。'),sources=[S('rhythmic'),O('rhythmic')]),
E('rhythmical','英、美 /ˈrɪðmɪkəl/','有节奏的；有韵律的','一下一下有起伏地重复，像走路、摇动或诗句念出来的韵律。','现代词形可看作 rhythmic + -al，整体属于希腊 rhythmikos 经拉丁等语言传入的形容词族。rhythmical 的英语早期记录也很早，不能只凭现代拆法断言它必定晚于 rhythmic。',[['希腊 rhythmos → rhythmikos，拉丁 rhythmicus','节律及其形容词形式'],['英语 rhythmic／rhythmical 形容词族','历史记录不按现代后缀长度简单排序'],['现代 rhythmical','有节奏、富有韵律的']],'rhythmical movement 和 rhythmic movement 通常都能表达有节奏的运动。rhythmical 稍长一些，不自带一种更高级或更悦耳的节奏；固定项目名称一般仍说 rhythmic gymnastics。','rhythmical movement；rhythmical breathing；a rhythmical pattern；rhythmical prose。','rhythmic 与 rhythmical 大多同义，学习时认出两种形式即可。它们不等于 rhyming“押韵的”。',('The boat’s rhythmical rocking made the passengers sleepy.','船身有节奏的摇晃让乘客昏昏欲睡。'),('The writer uses short sentences to create a rhythmical effect.','作者用短句营造富有韵律的效果。'),sources=[S('rhythmic'),O('rhythmic'),M('rhythmical')]),
E('rhythmically','英、美 /ˈrɪðmɪkli/','有节奏地；在节奏方面','说明动作怎样发生：按一定的强弱、长短或拍点进行。','rhythmical + -ly，亦可从 rhythmic + -ally 理解现代形式；远接希腊 rhythmikos。常见读法压缩为 /ˈrɪðmɪkli/，不需要把每个字母都念出一个音节。',[['希腊 rhythmikos → 英语 rhythmic／rhythmical','有节律的'],['英语形容词 + 副词词尾 → rhythmically','有节律地'],['动作或音乐评论','clap rhythmically；rhythmically complex']],'clap rhythmically 是按节奏拍手；rhythmically complex 则是“在节奏上很复杂”。前者修饰动作的方式，后者说明评价的是音乐哪一方面。','move rhythmically；clap rhythmically；tap rhythmically；rhythmically complex。','rhythmic 是“有节奏的声音”，rhythmically 是“有节奏地敲击”。不要用形容词直接替代修饰动作的副词。',('The children clapped rhythmically as the dancers entered.','舞者入场时，孩子们有节奏地拍着手。'),('The melody is simple, but the accompaniment is rhythmically demanding.','旋律很简单，但伴奏在节奏上要求很高。'),sources=[O('rhythmically'),S('rhythmic'),K('rhythmically')]),
E('rhyme','英、美 /raɪm/','名词：押韵、韵文、押韵词；动词：押韵、使押韵','两个词结尾听起来相配，如 light 和 night。注意听声音，不是只看最后几个字母。','名词经古法语 rime、动词经 rimer 进入中古英语 rime／rimen；远接拉丁 rhythmus、希腊 rhythmos。后来拼写受古典形式和 rhythm 影响而成为 rhyme；两词同族，但现代意思和读音已经分开。',[['希腊 rhythmos → 拉丁 rhythmus／rithmus','诗歌的节律'],['古法语 rime 与 rimer → 中古英语 rime／rimen','韵文；作韵文、押韵'],['拼写调整 → 英语 rhyme','结尾声音相配；押韵的诗或词']],'rhyme with... 是“与……押韵”。a nursery rhyme 是儿歌、童谣，通常有便于记忆的韵律。短语 without rhyme or reason 不是说没有诗歌，而是说看不出道理或规律。','rhyme with something；a rhyme for a word；a nursery rhyme；a rhyme scheme；without rhyme or reason。','rhythm 是节奏，rhyme 是韵脚的声音相配。一个句子可以有鲜明节奏，却没有任何押韵。',('“Night” rhymes with “light,” but “love” does not rhyme with “move.”','night 与 light 押韵，但 love 与 move 并不押韵。'),('She remembered the nursery rhyme her grandfather used to sing.','她还记得爷爷以前唱的那首童谣。'),sources=[S('rhyme'),O('rhyme_1'),O('rhyme_2')]),
E('rhyming','英、美 /ˈraɪmɪŋ/','押韵的；正在押韵、编韵文','让词语的结尾彼此呼应，读到后一行时，耳朵能认出前面出现过的相似声音。','英语 rhyme 去掉词尾 e 加 -ing；动词 rhyme 经古法语 rimer、中古英语 rimen 传来，名词支线是 rime。',[['拉丁 rhythmus → 古法语 rime／rimer','韵律、韵文；押韵'],['中古英语 rimen → 英语 rhyme','押韵'],['rhyme + -ing → rhyming','分词；形容词“押韵的”']],'rhyming words 是押韵词；rhyming couplets 是两行一组、尾音相押的诗句。a rhyming dictionary 按声音帮助找押韵词，和普通字母顺序词典用途不同。','rhyming words；rhyming couplets；a rhyming dictionary；rhyming slang。','rhyming 说声音的尾部相配；rhythmic 说节奏安排。rhyming verse 不一定节奏单调，也不一定都是儿歌。',('The class made a list of rhyming words for the poem.','全班为这首诗列出了一张押韵词表。'),('He wrote the invitation in rhyming couplets.','他用押韵的双行诗写了那封邀请函。'),sources=[S('rhyme'),K('rhyming'),O('rhyming')]),
E('arrhythmic','/əˈrɪðmɪk/；亦 /eɪˈrɪðmɪk/','缺乏规则节奏的；心律失常的','预期中的节奏被打乱，没有按通常模式稳定地进行。','来自希腊 arrhythmos“无节律的”，经现代拉丁等学术形式进入英语；a- 表否定，rhythmos 是节律。双 r 属于古典拼写；现代可以与 rhythmic、arrhythmia 对照，但不是必须从后出的英语名词逆推。',[['希腊 a- + rhythmos → arrhythmos','无、不 + 节律 → 无节律的'],['现代学术拉丁形式 → 英语 arrhythmic','没有规则节奏的'],['音乐及医学语境','不规则的节拍；与心律失常有关的']],'arrhythmic tapping 可以描写没有稳定模式的敲击。医疗语境中的 arrhythmic activity 则涉及异常心律，不只是“心跳比平时快”；是否异常取决于具体记录和情况。','an arrhythmic pattern；arrhythmic activity；arrhythmic beats。','arrhythmic 是形容词；arrhythmia 是心律失常的名词。无节奏也不等于完全停止，不能按 a- 把它理解成“没有心跳”。',('The irregular knocks formed an arrhythmic pattern.','那些不规则的敲击构成了没有稳定节奏的模式。'),('The report described episodes of arrhythmic activity.','报告描述了数次心律异常活动。'),sources=[S('arrhythmic'),M('arrhythmic'),K('arrhythmic'),'https://www.nhlbi.nih.gov/health/arrhythmias']),
E('polyrhythm','美 /ˈpɑːliˌrɪðəm/','复节奏；不同节奏同时叠合','两只手在同一段时间里各走各的节奏：一边均匀敲两下，另一边均匀敲三下，合起来形成交错感。','现代英语 poly-“多个”+ rhythm。poly- 来自希腊 polys“多”，rhythm 远接希腊 rhythmos；是现代音乐术语，不是某个古希腊完整名词原封借来。',[['希腊 polys“多”与 rhythmos“节律”','提供现代构词材料'],['英语 poly- + rhythm → polyrhythm','多种节奏并存'],['音乐中的具体结构','不同节奏在同一时间框架里交错']],'polyrhythm 不是一首歌里先后出现很多节奏，而是不同节奏同时组合。最容易想象的是三对二：同样长的一段时间，一条声部三等分，另一条两等分。','a three-against-two polyrhythm；play polyrhythms；complex polyrhythms。','a rhythm change 是先后换节奏；a polyrhythm 是同时叠加。polyphonic 强调多个相对独立的声部，并不自动表示这些声部构成复节奏。',('The exercise combines three beats against two to create a polyrhythm.','这个练习把三拍对两拍组合起来，形成复节奏。'),('The percussionists maintained different patterns within the same polyrhythm.','打击乐手在同一个复节奏中各自保持不同的节奏型。'),sources=[M('polyrhythm'),K('polyrhythm')]),
E('rheumatism','英、美 /ˈruːmətɪzəm/','风湿病；较笼统或旧式的关节、肌肉等疼痛疾病称呼','这是一个范围较宽的旧名称，常用来笼统地说关节或周围组织疼痛、僵硬等问题。','经拉丁 rheumatismus，或法语 rhumatisme，接希腊 rheumatismos，基础 rheuma 是“流出物、流动”。古人把某些疼痛归因于体内液体流动失衡；这是命名史，不是现代病因解释。',[['希腊 rhein → rheuma → rheumatismos','流动 → 流出物 → 古代相关病症名称'],['拉丁 rheumatismus／法语 rhumatisme → 英语 rheumatism','旧医学名词传入'],['英语意义集中于疼痛疾病','关节、肌肉等疼痛的笼统名称']],'在老小说里，a touch of rheumatism 常是人物说自己有点风湿痛。今天医学通常会进一步使用具体病名，所以单凭 rheumatism 不能知道是哪一种疾病。它也不等于专指 rheumatoid arthritis。','suffer from rheumatism；rheumatism in the joints；a history of rheumatism。','arthritis 强调关节炎症；rheumatism 是范围更模糊的旧称。不能把所有“风湿”一律翻译成类风湿关节炎。',('In the memoir, he often complains of rheumatism in his hands.','在回忆录中，他常抱怨双手的风湿痛。'),('The old record used the broad term “rheumatism” without naming a specific condition.','那份旧记录只笼统写了“风湿病”，没有说明具体疾病。'),sources=[S('rheumatism'),O('rheumatism'),RHE]),
E('rheumatic','英、美 /ruːˈmætɪk/','风湿病的；与风湿性疾病有关的','给疾病、疼痛或症状贴上“风湿性疾病这一范围”的说明，但还需要后面的名词说清具体情况。','经法语 reumatique／rheumatique 与拉丁 rheumaticus，接希腊 rheumatikos“与流出物有关的”。它的英语记录很早，不是从现代 rheumatism 删除 -ism 后才开始使用。',[['希腊 rheuma → rheumatikos','流出物 → 与之有关的'],['拉丁 rheumaticus → 法语 reumatique → 英语 rheumatic','早期医学形容词'],['现代词义发展','与风湿性疾病相关的']],'rheumatic diseases 是一大类风湿性疾病，不是一个单独病名。rheumatic fever 是“风湿热”这一特定名称，不能按字面当作所有风湿病发烧。这个词要和后面的名词一起读。','rheumatic disease；rheumatic pain；rheumatic fever；rheumatic heart disease。','rheumatic 范围较广；rheumatoid 常见于 rheumatoid arthritis“类风湿关节炎”这一具体名称。两词不能随意互换。',('The hospital has a clinic for rheumatic diseases.','这家医院设有风湿性疾病门诊。'),('The article distinguishes rheumatic fever from rheumatoid arthritis.','文章区分了风湿热和类风湿关节炎。'),sources=[S('rheumatic'),O('rheumatic'),RHE,'https://www.cdc.gov/group-a-strep/about/rheumatic-fever.html']),
E('rheumatology','英 /ˌruːməˈtɒlədʒi/；美 /ˌruːməˈtɑːlədʒi/','风湿病学；风湿科','不是只研究一个“风湿”病名，而是处理关节、肌肉、结缔组织及相关免疫疾病的一门医学专科。','近代学术构词 rheumat- + -ology；rheumat- 是希腊 rheuma 的词干形式，沿用风湿病词族，-ology 表研究领域。现代专业内容已经超出古代“体液流动”的观念。',[['希腊 rheuma／rheumat-','流动、流出物；旧病名词族的基础'],['近代 rheumat- + -ology → rheumatology','研究风湿性疾病的学科'],['现代临床专科','关节、肌肉、结缔组织及相关免疫问题']],'a rheumatology department 是风湿科，可能涉及类风湿关节炎、狼疮等不同疾病。医院名称有时会写“风湿免疫科”；英语 rheumatology 本身就常涵盖相关免疫性问题。','the rheumatology department；a rheumatology clinic；training in rheumatology。','rheumatology 是学科或科室；rheumatologist 是该领域的医生。它与主要侧重骨骼肌肉手术的 orthopaedics 有交集，但不是同一个专业。',('She works in the hospital’s rheumatology department.','她在医院的风湿科工作。'),('The course introduces research methods used in rheumatology.','这门课程介绍风湿病学研究所用的方法。'),sources=[O('rheumatology'),M('rheumatology'),K('rheumatology'),RHE]),
E('rheumatologist','英 /ˌruːməˈtɒlədʒɪst/；美 /ˌruːməˈtɑːlədʒɪst/','风湿科医生；风湿病学专家','专门研究、诊治风湿性和相关肌肉骨骼疾病的医生。','由 rheumatology 词族加表示从业者的 -ist，词形表现为 rheumatolog- + -ist；不是把完整 -ology 后面直接再拼一个 -ist。',[['希腊 rheumat- + 学术词尾 -ology → rheumatology','风湿病学'],['英语 rheumatolog- + -ist → rheumatologist','从事这一专科的人'],['现代职业名称','风湿科医生、相关专科专家']],'see a rheumatologist 是去看风湿科医生，consult a rheumatologist 是请这类专科医生评估。这里的 -ologist 是专业人员的词形，不能把他理解成只做实验、不接触患者的研究者。','see／consult a rheumatologist；a consultant rheumatologist；a paediatric rheumatologist。','rheumatism 是疾病旧称，rheumatology 是专业，rheumatologist 是人。词尾变化对应的不是病情轻重，而是词所指的对象。',('Her doctor referred her to a rheumatologist for further assessment.','她的医生转介她去风湿科作进一步评估。'),('The rheumatologist discussed the findings with the rest of the care team.','风湿科医生与医疗团队的其他成员讨论了检查发现。'),sources=[M('rheumatologist'),K('rheumatologist'),RHE]),
E('rheostat','英 /ˈriːəstæt/；美 /ˈriːəˌstæt/','变阻器；用改变电阻来调节电流的器件','像给电流通过的路设置一个可以调节的阻力，让通过的电流随之改变。','近代造词 rheo-“流、电流”+ -stat“使稳定、停留的器件”；分别接希腊 rhein“流”与站立、使停住的词族。它不是由 thermometer 或 thermostat 改出来的。',[['希腊 rhein 与 -statēs 相关词族','流动；使站住、维持'],['近代英语 rheo- + -stat → rheostat','调节电流的电学器件'],['现代电路用语','通过可变电阻调节电流']],'rheostat 的核心是可变电阻。老式装置可用它调节灯的亮度等，但现代所有调光器并不都用这种方式。理解词时抓住“电阻可调”，不必把 -stat 生搬成电流彻底静止。','a variable rheostat；adjust a rheostat；a rheostat in a circuit。','resistor 是电阻器的总称；rheostat 特别用于可调电阻、电流控制。thermostat 控温，两者都带 -stat，却控制不同对象。',('The diagram shows a rheostat connected to the lamp circuit.','图中画出了与灯电路相连的变阻器。'),('The old apparatus used a rheostat to vary the current.','那台旧装置用变阻器改变电流。'),sources=[M('rheostat'),K('rheostat')]),
E('diarrhea','英式 diarrhoea：/ˌdaɪəˈrɪə/；美式 diarrhea：/ˌdaɪəˈriːə/','腹泻；拉肚子','排便比平时更频繁，而且粪便稀、水分多；日常说“拉肚子”所指的常见症状。','经古法语 diarrie、晚期拉丁 diarrhoea，接希腊 diarrhoia，来自 diarrhein“流过”：dia-“穿过”+ rhein“流动”。后来拼写重新靠近拉丁形式，美式省去 oe 中的 o。',[['希腊 dia- + rhein → diarrhein／diarrhoia','穿过 + 流动 → 流泄、腹泻'],['晚期拉丁 diarrhoea → 古法语 diarrie → 中古英语','医学名称传入'],['现代两种拼写','diarrhoea〔英〕／diarrhea〔美〕，同一个词']],'diarrhea 通常不可数，说 have diarrhea。它描述一种症状，并不单独说明病因；感染、饮食或其他问题都可能涉及这个词。不要与普通 stomachache“肚子痛”混为一谈，腹痛与腹泻可以一起发生，也可以分别出现。','have diarrhea；an episode of diarrhea；acute／chronic diarrhea。','diarrhea 是稀便、排便增加；constipation 是便秘。diarrhoea 不是更严重的一种病，只是英式拼写。',('The questionnaire asked whether the patient had experienced diarrhea.','问卷询问患者是否出现过腹泻。'),('The British leaflet spells the word “diarrhoea.”','这份英国宣传页把这个词拼作 diarrhoea。'),sources=[S('diarrhea'),O('diarrhoea'),'https://www.niddk.nih.gov/health-information/digestive-diseases/diarrhea/definition-facts']),
E('gonorrhea','英式 gonorrhoea：/ˌɡɒnəˈrɪə/；美式 gonorrhea：/ˌɡɑːnəˈriːə/','淋病','这是一个特定细菌感染的病名，常在性健康、传染病与公共卫生资料中出现。','经晚期拉丁 gonorrhoia 借自希腊 gonorrhoia，gonos“种子、精液”+ rhoia“流出”。古人曾把相关分泌物误认为精液；这一误认留在名字里，不是现代对疾病的定义。',[['希腊 gonos + rhoia → gonorrhoia','精液 + 流出：带有古代误认的病名'],['晚期拉丁 gonorrhoia → 英语','病名进入英语'],['现代 gonorrhea／gonorrhoea','同一细菌感染的美式／英式名称']],'现代 gonorrhea 指淋病奈瑟菌感染，可以影响生殖道、直肠、咽喉等部位。它不只限于男性，也不能根据名字推断一定出现肉眼可见的分泌物。学词时把“历史为什么这样命名”和“今天这个词指什么”分开。','a gonorrhea test；gonorrhea infection；gonorrhea screening；drug-resistant gonorrhea。','gonorrhea 是一种具体感染；STI 是性传播感染的总称。gonorrhoea 多出的 o 是拼写传统，不改变意思。',('The public health report included data on gonorrhea.','这份公共卫生报告包含了淋病的数据。'),('The clinic provides information about gonorrhea and other sexually transmitted infections.','这家诊所提供有关淋病及其他性传播感染的信息。'),sources=[S('gonorrhea'),O('gonorrhoea'),'https://www.cdc.gov/gonorrhea/about/index.html']),
]
EX={w:'较冷门的专科、仪器、地理或古代器物术语，按用户通用阅读优先要求暂略。' for w in 'rheum antiarrhythmic dysrhythmia rheometer logorrhea rhyton endorheic eurhythmia eurhythmic hemorrhea eurhythmy'.split()}
EX.update({'diarrhoea':'英式拼写已并入 diarrhea 的完整词条。','gonorrhoea':'英式拼写已并入 gonorrhea 的完整词条。'})
ROOT=dict(id='C1221',meaning='流动；有节律的运动；相关分泌物旧名',core='希腊 rhein 是流动。水流的意象后来连到有秩序的运动 rhythmos，也进入身体流出物 rheuma 一类旧医学名称。',image='有安排的运动 → rhythm；诗句尾音相呼应 → rhyme；电流可调 → rheostat；体液旧观念留下的病名 → rheumatism；流过、流泄 → diarrhea。',intro='这组不需要把每个词都想成水龙头。音乐支线抓住时间里的长短和重复；医学支线了解命名历史即可，今天的定义要按现代医学理解。',forms='rhe-／rheo- 接流动；rheumat- 接 rheuma 的词干；-rrhea／-rrhoea 常见于流出相关名称。rhythm 与 rhyme 同族但现代含义分工不同，且拼写演变交织，不能说一个现代英语词简单生出了另一个。',branches=[['节奏与押韵','rhythm, rhythmic, rhythmical, rhythmically, rhyme, rhyming, polyrhythm'],['节律异常','arrhythmia, arrhythmic'],['风湿医学词族','rheumatism, rheumatic, rheumatoid, rheumatology, rheumatologist'],['流动及名称','rheology, rheostat, diarrhea, gonorrhea']],contrasts='rhythm 说节奏，rhyme 说押韵；rheumatic 是宽泛相关形容词，rheumatoid 常进入特定病名。古人以体液解释 rheumatism、误认分泌物而命名 gonorrhea，这些都不能拿来当现代病因。',practice='The poem has a strong rhythm even though its lines do not rhyme. 这首诗虽然各行不押韵，却有鲜明的节奏。把节奏与尾音分开听，会更容易记住这两个词。',words=[],exclude=EX)
if __name__=='__main__':
 m=json.loads((BASE/'.cache/batch200/rewrite_vid.json').read_text());r=next(x for x in m['roots'] if x['id']==ROOT['id']);ROOT['words']=[w for w in r['family'] if '-' not in w and w not in EX]
